import {seed,uid,clone,monday,week,subject,validateState,conflicts,reasons,missing,replacements,audit,slotTime} from '/shared/engine.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'▦',calendar:'▤',teachers:'♙',classes:'▧',rooms:'▥',rules:'⚙',reports:'◴',history:'↶',assistant:'✦',accounts:'♧',data:'⇅'};
let state,revision=0,mode='local',user=null,ai=false,view='calendar',key=monday(),scope='class',selected='',query='',past=[],future=[],saving=false,blocked=false,busy=false,lastAction='',proposal=null;
const canEdit=()=>!user||user.role==='admin';
const entries=()=>week(state,key).sessions;
const scheduleState=()=>week(state,key).snapshot||state;
const current=()=>week(state,key);
const btn=(label,action,kind='',attrs='')=>`<button class="btn ${kind}" data-action="${action}" ${attrs}>${label}</button>`;
const input=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,items,value='')=>`<label>${label}<select name="${name}">${items.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const empty=(title,text)=>`<div class="empty"><span>◇</span><h3>${title}</h3><p>${text}</p></div>`;
function toast(text,error=false){$('#toast').textContent=text;$('#toast').className=error?'show error':'show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').className='',6000);}
async function api(path,options={}){const r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const b=await r.json();if(!r.ok)throw Object.assign(new Error(b.error||'Request failed'),{status:r.status});return b;}
function modal(title,body,onSubmit,wide=false){const d=$('#modal');if(d.open)d.close();d.innerHTML=`<form id="dialog-form"><header><div><span class="eyebrow">TRAINING STUDIO</span><h2>${title}</h2></div><button type="button" class="icon-btn" data-action="close" aria-label="Close dialog">×</button></header><div class="dialog-body">${body}</div></form>`;d.className=wide?'wide':'';d.showModal();d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await onSubmit?.(new FormData(e.target),e.target);}catch(err){toast(err.message,true);}};}
function close(){$('#modal').close();}
function ensureWeek(s){if(!s.weeks[key])s.weeks[key]={sessions:[],published:false};return s.weeks[key];}
function editable(){if(!canEdit()){toast('Only administrators can edit schedules.',true);return false;}if(saving||busy){toast('Please wait for the current operation.');return false;}if(blocked){toast('Resolve the save error before making more changes.',true);return false;}return true;}
function editableWeek(){if(!editable())return false;if(current().published){toast('Unpublish this week before editing it.',true);return false;}return true;}
async function persist(label){saving=true;lastAction=label;render();try{if(mode==='server'){const r=await api('/state',{method:'PUT',body:JSON.stringify({state,revision,action:label})});revision=r.revision;state.log=r.log;}else localStorage.setItem('training-studio-v2',JSON.stringify(state));blocked=false;}catch(err){blocked=true;toast(err.message,true);}finally{saving=false;render();}}
async function commit(next,label,history=true){if(saving||blocked)throw new Error('Wait for the current save or resolve the save error before continuing.');const errors=validateState(next);if(errors.length)throw new Error(errors.slice(0,4).join(' '));for(const [k,w]of Object.entries(next.weeks))if(w.published&&conflicts(w.snapshot||next,w.sessions).length)throw new Error(`This change conflicts with published week ${k}. Unpublish it first.`);if(history){past.push(clone(state));past=past.slice(-30);future=[];}state=next;audit(state,label,user?.name);close();await persist(label);}
function heading(title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">YOUR ACADEMY, IN SYNC</span><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function render(){if(!state)return;const display=scheduleState();const items=scope==='class'?display.classes:scope==='teacher'?display.teachers:display.rooms;if(!items.some(x=>x.id===selected))selected=items[0]?.id||'';const all=entries(),issues=conflicts(scheduleState(),all),unfilled=missing(scheduleState(),all).reduce((n,x)=>n+x.remaining,0);const writable=canEdit();
 const nav=[['calendar','Timetable'],['teachers','Teachers'],['classes','Classes & subjects'],['rooms','Rooms'],['reports','Insights'],['history','Weekly history'],...(writable?[['rules','Scheduling rules'],['assistant','Assistant'],['data','Import & export'],['accounts','Accounts']]:[])];
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="/"><span class="brand-mark">T</span><span>Training<span class="brand-light">Studio</span></span></a><div class="workspace-tag"><span class="workspace-icon">A</span><div><strong>${esc(state.school)}</strong><small>${mode==='server'?'Shared workspace':'Local workspace · this browser'}</small></div></div><span class="nav-label">WORKSPACE</span><nav>${nav.map(([id,label])=>`<button data-view="${id}" class="nav-item ${view===id?'active':''}"><span>${icons[id]}</span>${label}${id==='calendar'?'<b>'+all.length+'</b>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-orbit">✦</div><strong>A little structure.<br>A better training week.</strong><p>Plan with confidence.</p></div><div class="profile"><span>${esc((user?.name||'Local administrator').slice(0,1))}</span><div><strong>${esc(user?.name||'Local administrator')}</strong><small>${writable?'Administrator':'Teacher · view only'}</small></div>${mode==='server'?btn('↪','logout','icon-btn','aria-label="Sign out"'):''}</div></aside><main><div class="topbar"><div class="breadcrumb">Workspace <span>/</span> ${esc(nav.find(x=>x[0]===view)?.[1]||'Timetable')}</div><div class="top-actions">${mode==='server'?btn('Sign out','logout','mobile-signout'): ''}<span class="save-status ${blocked?'danger':''}">${saving?'Saving…':blocked?'Changes not saved':mode==='server'?'Saved to workspace':'Saved on this device'}</span>${writable?btn('↶','undo','icon-btn',`aria-label="Undo" ${!past.length||saving?'disabled':''}`)+btn('↷','redo','icon-btn',`aria-label="Redo" ${!future.length||saving?'disabled':''}`):''}</div></div>${blocked?`<div class="banner warning">Your changes are not saved. Download a backup before reloading if another administrator changed the workspace. ${btn('Retry save','retry')}${btn('Download backup','backup')}${btn('Reload saved version','reload')}</div>`:''}<div class="content">${view==='calendar'?calendarView(issues,unfilled):view==='teachers'?teacherView():view==='classes'?classView():view==='rooms'?roomView():view==='rules'?rulesView():view==='reports'?reportView():view==='history'?historyView():view==='assistant'?assistantView():view==='accounts'?accountsView():dataView()}</div><footer>Training Studio <span>Weekly planning, thoughtfully organized.</span></footer></main></div>`;
 if(view==='accounts'&&mode==='server')loadUsers();
}
function calendarView(issues,unfilled){const state=scheduleState();const all=entries();const itemList=scope==='class'?state.classes:scope==='teacher'?state.teachers:state.rooms;const field=scope==='class'?'classId':scope==='teacher'?'teacherId':'roomId';const shown=all.filter(e=>e[field]===selected);const isAdmin=canEdit();return heading('A clear plan for every week.','Bring your people, spaces and subjects together.',isAdmin?btn('＋ Add session','add-session','')+btn(busy?'<span class="spinner"></span> Planning…':'✦ Generate timetable','generate','primary',busy?'disabled':''):'')+`<div class="stats-grid"><article class="stat blue"><span>Scheduled periods</span><strong>${all.length}<small> this week</small></strong><div class="stat-detail">Across ${state.classes.length} classes</div><i>▦</i></article><article class="stat mint"><span>Teachers scheduled</span><strong>${new Set(all.map(x=>x.teacherId)).size}<small> / ${state.teachers.length}</small></strong><div class="stat-detail">Availability-aware planning</div><i>♙</i></article><article class="stat peach"><span>Unfilled periods</span><strong>${isAdmin?unfilled:'—'}</strong><div class="stat-detail">${isAdmin?'Weekly subject requirements':'Your published sessions only'}</div><i>◷</i></article><article class="stat lavender"><span>Conflicts</span><strong>${issues.length}</strong><div class="stat-detail">${issues.length?'Review before publishing':'No clashes in this schedule'}</div><i>◇</i></article></div><section class="panel timetable-panel"><div class="panel-heading"><div><h2>Weekly timetable <span class="badge ${current().published?'green':''}">${current().published?'Published':'Draft'}</span></h2><p>${esc(itemList.find(x=>x.id===selected)?.name||'Add a class to begin')} · ${shown.length} periods</p></div><div class="actions">${btn('‹','prev-week','icon-btn','aria-label="Previous week"')}<input aria-label="Week starting" id="week-input" type="date" value="${key}">${btn('›','next-week','icon-btn','aria-label="Next week"')}${btn('Print / PDF','print')}${isAdmin?btn(current().published?'Unpublish':'Publish week','publish',current().published?'':'success'):''}</div></div><div class="table-tools"><div class="segmented">${['class','teacher','room'].map(x=>`<button data-scope="${x}" class="${scope===x?'selected':''}">By ${x}</button>`).join('')}</div><select id="entity-select" aria-label="Select ${scope}">${itemList.map(x=>`<option value="${x.id}" ${selected===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><span class="table-hint">${isAdmin?'Drag to move · click to edit · lock to keep':'Published sessions assigned to you'}</span></div><div class="table-scroll"><table class="schedule"><thead><tr><th>Time</th>${state.rules.days.map((d,i)=>`<th>${esc(d)}<span>${dayDate(i)}</span></th>`).join('')}</tr></thead><tbody>${Array.from({length:state.rules.periods},(_,p)=>`<tr><th><strong>${slotTime(state.rules,p)}</strong><small>${slotTime(state.rules,p+1)}</small></th>${state.rules.days.map((d,day)=>{if(state.rules.breaks.includes(p))return '<td class="break-cell">Break · recharge</td>';const list=shown.filter(e=>e.day===day&&e.period===p);return `<td data-drop-day="${day}" data-drop-period="${p}">${list.length?list.map(e=>{const sub=subject(state,e),c=state.classes.find(x=>x.id===e.classId),t=state.teachers.find(x=>x.id===e.teacherId),r=state.rooms.find(x=>x.id===e.roomId);const color=Math.max(0,state.classes.findIndex(x=>x.id===e.classId))%4;return `<button class="session color-${color} ${reasons(state,all,e).length?'has-conflict':''}" data-session="${e.id}" draggable="${isAdmin&&!current().published&&!e.locked}" aria-label="${esc(sub?.name)} ${esc(d)} ${slotTime(state.rules,p)}${e.locked?' locked':''}"><span class="session-code">${esc(c?.name)} <span>${e.locked?'▣':''}</span></span><strong>${esc(sub?.name||'Missing subject')}</strong><small>${esc(t?.name||'Missing teacher')}</small><span class="session-room">${esc(r?.name||'Missing room')}</span></button>`;}).join(''):isAdmin?`<button class="empty-slot" data-add-day="${day}" data-add-period="${p}" aria-label="Add session ${d} ${slotTime(state.rules,p)}">＋</button>`:'<span class="free-label">Free</span>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="table-footer"><span><i class="legend-dot"></i> ${current().published?'Published for teachers':'Draft · visible to administrators'}</span><span>${state.rules.duration} min / period · ${state.rules.breaks.length} break${state.rules.breaks.length!==1?'s':''} per day</span></div></section>${issues.length?`<section class="panel issue-panel"><h2>Needs attention</h2>${[...new Set(issues.map(x=>x.reason))].slice(0,8).map(x=>`<p class="issue">${esc(x)}</p>`).join('')}</section>`:''}`;}
function dayDate(i){const state=scheduleState();const d=new Date(key+'T00:00:00Z');const offsets={Monday:0,Tuesday:1,Wednesday:2,Thursday:3,Friday:4,Saturday:5,Sunday:6};d.setUTCDate(d.getUTCDate()+offsets[state.rules.days[i]]);return d.toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'});}
function teacherView(){return heading('The people behind the progress.','Qualifications, availability and balanced workloads.',canEdit()?btn('＋ Add teacher','add-teacher','primary'):'')+`<input class="search" id="search" placeholder="Search teachers or expertise…" aria-label="Search teachers" value="${esc(query)}"><div class="card-grid">${state.teachers.filter(t=>(t.name+' '+t.subjects.join(' ')).toLowerCase().includes(query.toLowerCase())).map((t,i)=>{const n=entries().filter(e=>e.teacherId===t.id).length;return `<article class="panel person-card"><div class="person-head"><span class="avatar color-${i%4}">${esc(t.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><h2>${esc(t.name)}</h2><p>Up to ${t.maxDaily} periods / day</p></div></div><div class="tags">${t.subjects.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="load-label"><span>Weekly workload</span><strong>${n} / ${t.maxWeekly}</strong></div><div class="progress"><i style="width:${Math.min(100,n/t.maxWeekly*100)}%"></i></div><p>${t.unavailable.length?t.unavailable.length+' availability restriction(s)':'Available during working hours'}</p>${canEdit()?`<div class="actions">${btn('Edit profile','edit-teacher','',`data-id="${t.id}"`)}${btn('Availability','availability','',`data-id="${t.id}"`)}</div>`:''}</article>`;}).join('')||empty('No teachers found','Add instructors and their exact subject qualifications.')}</div>`;}
function classView(){return heading('Every class, moving forward.','Manage course requirements separately from weekly timetables.',canEdit()?btn('＋ Add class','add-class','primary'):'')+`<input class="search" id="search" placeholder="Search classes or branches…" aria-label="Search classes" value="${esc(query)}"><div class="card-grid">${state.classes.filter(c=>(c.name+' '+c.branch).toLowerCase().includes(query.toLowerCase())).map((c,i)=>{const total=c.subjects.reduce((n,x)=>n+x.total,0),done=c.subjects.reduce((n,x)=>n+x.completed,0);return `<article class="panel class-card"><div class="person-head"><span class="avatar color-${i%4}">${esc(c.name)}</span><div><h2>${esc(c.branch)}</h2><p>Term ${c.term} · ${c.size} students</p></div></div><div class="subject-list">${c.subjects.map(s=>`<div><strong>${esc(s.name)}</strong><span>${s.weekly} / week</span></div>`).join('')||'<p>No subjects configured</p>'}</div><div class="load-label"><span>Course completion</span><strong>${total?Math.round(done/total*100):0}%</strong></div><div class="progress"><i style="width:${total?done/total*100:0}%"></i></div><p>${done} completed / ${total} total periods</p>${canEdit()?`<div class="actions">${btn('Edit class','edit-class','',`data-id="${c.id}"`)}${btn('Subjects & progress','subjects','',`data-id="${c.id}"`)}${btn('Promote','promote','',`data-id="${c.id}"`)}</div>`:''}</article>`;}).join('')||empty('No classes yet','Add your first class and its subjects.')}</div>`;}
function roomView(){return heading('A place for every session.','Match classes to room capacity and facilities.',canEdit()?btn('＋ Add room','add-room','primary'):'')+`<div class="card-grid">${state.rooms.map((r,i)=>`<article class="panel room-card"><div class="room-visual color-${i%4}"><span>▥</span><b>${esc(r.name)}</b></div><h2>${esc(r.name)}</h2><p>${esc(r.type)} · ${r.capacity} seats</p><div class="load-label"><span>Booked this week</span><strong>${entries().filter(e=>e.roomId===r.id).length} periods</strong></div>${canEdit()?btn('Edit room','edit-room','',`data-id="${r.id}"`):''}</article>`).join('')}</div>`;}
function rulesView(){const r=state.rules;return heading('Set the rhythm of your week.','Hard rules prevent clashes. Preferences guide the generator.')+`<form id="rules-form" class="panel settings"><h2>Academy & working hours</h2><div class="form-grid">${input('Academy name','school',state.school,'text','required maxlength="120"')}${input('First period starts','start',r.start,'time','required')}${input('Periods per day','periods',r.periods,'number','required min="1" max="12"')}${input('Minutes per period','duration',r.duration,'number','required min="15" max="180"')}</div><h3>Working days</h3><div class="checks">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<label><input type="checkbox" name="days" value="${d}" ${r.days.includes(d)?'checked':''}>${d}</label>`).join('')}</div>${input('Break periods (numbers separated by commas, e.g. 4)','breaks',r.breaks.map(x=>x+1).join(', '))}<p class="muted">All periods, including breaks, use the duration above. Changing days requires an empty timetable history to avoid shifting existing sessions to different days.</p><div class="rule-summary"><h3>Always enforced</h3><p>Teacher qualifications · availability · daily and weekly loads · no class, teacher or room clashes · room capacity and type · course and weekly requirements.</p><h3>Scheduling preferences</h3><p>Balanced class days, fewer teacher gaps, early placement and adjacent lab periods. Preferences are best effort and never override required rules.</p></div>${btn('Save rules','submit','primary','type="submit"')}</form>`;}
function reportView(){const state=scheduleState();const sessions=entries(),unfilled=missing(state,sessions),problems=conflicts(state,sessions);return heading('See where the week stands.','Workload, room utilization and scheduling gaps.',btn('Export Excel','export-excel')+btn('Print / PDF','print'))+`<div class="report-grid"><section class="panel"><h2>Teacher workload</h2><p>Scheduled periods / weekly limit</p><div class="bars">${state.teachers.map(t=>{const n=sessions.filter(e=>e.teacherId===t.id).length;return `<div class="bar-row"><span>${esc(t.name)}</span><div class="progress"><i style="width:${Math.min(100,n/t.maxWeekly*100)}%"></i></div><strong>${n}/${t.maxWeekly}</strong></div>`;}).join('')}</div></section><section class="panel"><h2>Room utilization</h2><p>Share of available teaching periods</p>${state.rooms.map(r=>{const n=sessions.filter(e=>e.roomId===r.id).length,capacity=state.rules.days.length*(state.rules.periods-state.rules.breaks.length);return `<div class="bar-row"><span>${esc(r.name)}</span><div class="progress mint-bar"><i style="width:${capacity?n/capacity*100:0}%"></i></div><strong>${capacity?Math.round(n/capacity*100):0}%</strong></div>`;}).join('')}</section></div><section class="panel"><h2>Unfilled requirements <span class="badge">${canEdit()?unfilled.reduce((n,x)=>n+x.remaining,0):'—'}</span></h2>${canEdit()?unfilled.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Class</th><th>Subject</th><th>Periods needed</th></tr></thead><tbody>${unfilled.map(x=>`<tr><td>${esc(x.className)}</td><td>${esc(x.subjectName)}</td><td>${x.remaining}</td></tr>`).join('')}</tbody></table>`:empty('All weekly requirements are filled','Review and publish the timetable when ready.'): '<p>Full-academy requirements are available to administrators.</p>'}</section><section class="panel"><h2>Conflict report</h2>${problems.length?problems.map(x=>`<p class="issue">${esc(x.reason)}</p>`).join(''): '<p>No conflicts found in these sessions.</p>'}</section>`;}
function historyView(){return heading('Good weeks are worth keeping.','Copy a week, return to a draft, or review published schedules.')+`<section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Week starting</th><th>Periods</th><th>Status</th><th>Actions</th></tr></thead><tbody>${Object.entries(state.weeks).sort((a,b)=>b[0].localeCompare(a[0])).map(([k,w])=>`<tr><td><strong>${k}</strong></td><td>${w.sessions.length}</td><td><span class="badge ${w.published?'green':''}">${w.published?'Published':'Draft'}</span></td><td><div class="actions">${btn('Open','open-week','',`data-id="${k}"`)}${canEdit()?btn('Copy','copy-week','',`data-id="${k}"`)+btn('Delete','delete-week','danger-ghost',`data-id="${k}"`):''}</div></td></tr>`).join('')}</tbody></table></div></section>${canEdit()?`<section class="panel"><h2>Recent activity</h2><div class="activity">${state.log.slice(0,25).map(x=>`<div><span class="activity-dot"></span><div><strong>${esc(x.label)}</strong><p>${esc(x.user)} · ${esc(new Date(x.at).toLocaleString())}</p></div></div>`).join('')||'<p>Your activity will appear here.</p>'}</div></section>`:''}`;}
function assistantView(){return heading('Keep the week moving.','Find replacements for an absent teacher and review every proposed change.')+`<div class="report-grid"><section class="panel assistant-card"><span class="assistant-orb">✦</span><h2>Absence planner</h2><p>Choose a teacher and day. Existing sessions stay in their slots while eligible replacements are checked.</p><form id="absence-form">${select('Absent teacher','teacherId',state.teachers.map(t=>[t.id,t.name]))}${select('Day','day',state.rules.days.map((d,i)=>[i,d]))}${btn('Find replacements','submit','primary','type="submit"')}</form></section><section class="panel"><span class="badge">${ai?'AI connected':'Optional AI integration'}</span><h2>Ask in your own words</h2><p>For example: “Sara Ahmed is unavailable on Tuesday. Suggest replacements.”</p><form id="ai-form"><label>Your request<textarea name="prompt" maxlength="2000" required ${!ai?'disabled':''}></textarea></label>${btn('Preview suggestion','submit','primary',`type="submit" ${!ai?'disabled':''}`)}</form>${!ai?'<p class="muted">AI is not connected in this workspace. The absence planner works without it.</p>':''}<div class="note">Suggestions never apply automatically. Every replacement must pass the scheduling rules, including locks.</div></section></div>`;}
function accountsView(){return heading('The right access for each person.','Administrators plan. Teachers see their published sessions.',mode==='server'?btn('＋ Add account','add-account','primary'):'')+(mode==='server'?'<section class="panel" id="users-list"><div class="skeleton"></div></section>':empty('Shared accounts require the server','This is a local workspace. Run the server version to enable secure sign-in and shared saved schedules.'));}
function dataView(){return heading('Your data, ready to move.','Keep backups and bring your academy records into one workspace.')+`<div class="card-grid"><section class="panel"><span class="feature-icon blue">⇩</span><h2>Backup & restore</h2><p>A full JSON backup includes your academy, rules, history and course progress.</p><div class="actions">${btn('Download backup','backup','primary')}${btn('Restore backup','restore')}</div></section><section class="panel"><span class="feature-icon mint">▦</span><h2>Excel & CSV</h2><p>Import teachers, classes, subjects and rooms. Download the template for exact columns and examples.</p><div class="actions">${btn('Get template','template')}${btn('Import spreadsheet','import-sheet')}${btn('Export timetable','export-excel','success')}</div></section><section class="panel"><span class="feature-icon peach">↶</span><h2>Original project data</h2><p>Import the original instructors, classes and curriculum. Missing curriculum stays visible for you to complete.</p>${btn('Preview original data','legacy')}${btn('Import old JSON backup','legacy-backup')}</section></div><section class="panel"><h2>Backup guidance</h2><p>${mode==='server'?'Shared changes save to the server database. Download periodic backups and keep the server data directory on persistent storage.':'Changes save in this browser. Clearing browser data removes this local workspace, so download backups regularly.'}</p><p>Modern backups restore exactly after validation. Old backups import teacher and class records; their HTML-based timetables must be rebuilt in the new scheduler.</p></section>`;}
const formActions=(id,kind)=>`<div class="dialog-actions">${id?btn('Delete '+kind,'delete-'+kind,'danger-ghost',`type="button" data-id="${id}"`):''}<span></span>${btn('Cancel','close','','type="button"')}<button class="btn primary" type="submit">Save changes</button></div>`;
function editTeacher(id){if(!editable())return;const t=state.teachers.find(x=>x.id===id)||{name:'',subjects:[],maxWeekly:25,maxDaily:5,unavailable:[]};modal(id?'Edit teacher':'Add teacher',`<div class="form-grid">${input('Full name','name',t.name,'text','required maxlength="120"')}${input('Weekly limit','maxWeekly',t.maxWeekly,'number','required min="1" max="84"')}${input('Daily limit','maxDaily',t.maxDaily,'number','required min="1" max="12"')}</div>${input('Qualified subjects (separated by commas)','subjects',t.subjects.join(', '),'text','required')}<p class="muted">Subject names must match the class curriculum. Matching is case-insensitive.</p>${formActions(id,'teacher')}`,async f=>{const next=clone(state);const record={...t,id:id||uid(),name:f.get('name').trim(),subjects:[...new Set(f.get('subjects').split(',').map(x=>x.trim()).filter(Boolean))],maxWeekly:+f.get('maxWeekly'),maxDaily:+f.get('maxDaily')};if(id)next.teachers[next.teachers.findIndex(x=>x.id===id)]=record;else next.teachers.push(record);await commit(next,id?'Updated teacher':'Added teacher');});}
function availability(id){if(!editable())return;const t=state.teachers.find(x=>x.id===id);modal('Availability · '+esc(t.name),`<p>Checked cells mean unavailable. These restrictions apply to every week.</p><div class="table-scroll"><table class="availability-table"><thead><tr><th>Day</th><th>All day</th>${Array.from({length:state.rules.periods},(_,p)=>`<th>${p+1}</th>`).join('')}</tr></thead><tbody>${state.rules.days.map((d,day)=>`<tr><th>${d}</th>${[-1,...Array.from({length:state.rules.periods},(_,p)=>p)].map(p=>`<td><input aria-label="Unavailable ${d} ${p===-1?'all day':'period '+(p+1)}" name="unavailable" type="checkbox" value="${day}:${p}" ${t.unavailable.some(x=>x.day===day&&x.period===p)?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button class="btn primary" type="submit">Save availability</button></div>`,async f=>{const next=clone(state);next.teachers.find(x=>x.id===id).unavailable=f.getAll('unavailable').map(v=>{const [day,period]=v.split(':').map(Number);return {day,period};});await commit(next,'Updated teacher availability');},true);}
function editClass(id){if(!editable())return;const c=state.classes.find(x=>x.id===id)||{name:'',branch:'CS',term:1,size:25,subjects:[]};modal(id?'Edit class':'Add class',`<div class="form-grid">${input('Class name','name',c.name,'text','required maxlength="120"')}${input('Branch / course','branch',c.branch,'text','required maxlength="120"')}${input('Term','term',c.term,'number','required min="1" max="20"')}${input('Student count','size',c.size,'number','required min="1" max="10000"')}</div>${formActions(id,'class')}`,async f=>{const next=clone(state),record={...c,id:id||uid(),name:f.get('name').trim(),branch:f.get('branch').trim(),term:+f.get('term'),size:+f.get('size')};if(id)next.classes[next.classes.findIndex(x=>x.id===id)]=record;else next.classes.push(record);await commit(next,id?'Updated class':'Added class');});}
function subjectRow(s={id:uid(),name:'',weekly:3,total:40,completed:0,roomType:'Any',double:false,early:false}){return `<div class="subject-editor" data-subject-id="${s.id}"><div class="form-grid">${input('Subject name','name',s.name,'text','required maxlength="120"')}${input('Periods / week','weekly',s.weekly,'number','required min="0" max="84"')}${input('Total course periods','total',s.total,'number','required min="0" max="10000"')}${input('Completed periods','completed',s.completed,'number','required min="0" max="10000"')}${select('Room type','roomType',[...new Set(['Any','Classroom','Lab',...state.rooms.map(r=>r.type),s.roomType])].map(x=>[x,x]),s.roomType)}</div><div class="checks"><label><input name="double" type="checkbox" ${s.double?'checked':''}>Prefer double periods</label><label><input name="early" type="checkbox" ${s.early?'checked':''}>Prefer early periods</label>${btn('Remove subject','remove-subject','danger-ghost','type="button"')}</div></div>`;}
function editSubjects(id){if(!editable())return;const c=state.classes.find(x=>x.id===id);modal('Subjects · '+esc(c.name),`<p>Completed periods represent lessons actually taught. Generating a timetable does not increase course completion.</p><div id="subject-editors">${c.subjects.map(subjectRow).join('')}</div>${btn('＋ Add subject','add-subject','','type="button"')}<div class="dialog-actions"><button class="btn primary" type="submit">Save curriculum</button></div>`,async(_,form)=>{const subs=[...form.querySelectorAll('.subject-editor')].map(row=>{const get=n=>row.querySelector(`[name="${n}"]`);return {id:row.dataset.subjectId,name:get('name').value.trim(),weekly:+get('weekly').value,total:+get('total').value,completed:+get('completed').value,roomType:get('roomType').value,double:get('double').checked,early:get('early').checked};});const removed=c.subjects.filter(s=>!subs.some(x=>x.id===s.id));if(Object.values(state.weeks).some(w=>w.sessions.some(e=>e.classId===id&&removed.some(s=>s.id===e.subjectId))))throw new Error('A removed subject is referenced by a saved timetable. Remove those sessions first.');const next=clone(state);next.classes.find(x=>x.id===id).subjects=subs;await commit(next,'Updated curriculum and course progress');},true);}
function editRoom(id){if(!editable())return;const r=state.rooms.find(x=>x.id===id)||{name:'',capacity:30,type:'Classroom'};modal(id?'Edit room':'Add room',`<div class="form-grid">${input('Room name','name',r.name,'text','required maxlength="120"')}${input('Capacity','capacity',r.capacity,'number','required min="1" max="10000"')}${input('Room type','type',r.type,'text','required maxlength="120"')}</div>${formActions(id,'room')}`,async f=>{const next=clone(state),record={id:id||uid(),name:f.get('name').trim(),capacity:+f.get('capacity'),type:f.get('type').trim()};if(id)next.rooms[next.rooms.findIndex(x=>x.id===id)]=record;else next.rooms.push(record);await commit(next,id?'Updated room':'Added room');});}
function confirmAction(title,message,action){modal(title,`<p>${message}</p><div class="dialog-actions">${btn('Cancel','close','','type="button"')}<button type="submit" class="btn primary">Confirm</button></div>`,action);}
function deleteEntity(kind,id){if(!editable())return;const field=kind+'Id',collection=kind==='class'?'classes':kind==='teacher'?'teachers':'rooms';if(Object.values(state.weeks).some(w=>w.sessions.some(e=>e[field]===id)))return toast('This record is used in saved timetables. Remove its sessions before deleting it.',true);confirmAction('Delete '+kind+'?','This removes the record. You can undo the change.',async()=>{const next=clone(state);next[collection]=next[collection].filter(x=>x.id!==id);await commit(next,'Deleted '+kind);});}
function sessionDialog(id,day=0,period=0){const e=entries().find(x=>x.id===id);if(!canEdit()){if(e){const state=scheduleState();const t=state.teachers.find(t=>t.id===e.teacherId);modal('Session details',`<h3>${esc(subject(state,e)?.name)}</h3><p>${esc(t?.name)} · ${esc(state.rules.days[e.day])} · ${slotTime(state.rules,e.period)}</p>`,null);}return;}
 if(!editableWeek())return;if(!state.classes.length||!state.teachers.length||!state.rooms.length)return toast('Add classes, teachers and rooms first.',true);
 const c=state.classes.find(x=>x.id===(e?.classId||(scope==='class'?selected:'')))||state.classes[0];
 modal(e?'Edit session':'Add session',`${e?.locked?'<div class="note">This session is locked. Unlock it in this dialog before changing its assignment.</div>':''}<div class="form-grid">${select('Class','classId',state.classes.map(x=>[x.id,x.name]),c.id)}${select('Subject','subjectId',c.subjects.map(x=>[x.id,x.name]),e?.subjectId)}${select('Teacher','teacherId',state.teachers.map(x=>[x.id,x.name]),e?.teacherId||(scope==='teacher'?selected:''))}${select('Room','roomId',state.rooms.map(x=>[x.id,x.name]),e?.roomId||(scope==='room'?selected:''))}${select('Day','day',state.rules.days.map((x,i)=>[i,x]),e?.day??day)}${select('Period','period',Array.from({length:state.rules.periods},(_,i)=>[i,`${i+1} · ${slotTime(state.rules,i)}${state.rules.breaks.includes(i)?' (break)':''}`]),e?.period??period)}</div><label class="check"><input name="locked" type="checkbox" ${e?.locked?'checked':''}>Lock this session during regeneration</label><div id="session-check" class="note"></div><div class="dialog-actions">${e?btn('Delete session','delete-session','danger-ghost',`type="button" data-id="${id}"`):''}<span></span><button class="btn primary" type="submit">Save session</button></div>`,async f=>{const record={id:id||uid(),classId:f.get('classId'),subjectId:f.get('subjectId'),teacherId:f.get('teacherId'),roomId:f.get('roomId'),day:+f.get('day'),period:+f.get('period'),locked:f.has('locked')};if(e?.locked&&record.locked&&['classId','subjectId','teacherId','roomId','day','period'].some(k=>record[k]!==e[k]))throw new Error('Uncheck the lock before changing this assignment.');const errors=reasons(state,entries(),record);if(errors.length)throw new Error(errors.join(' '));const next=clone(state),w=ensureWeek(next);w.sessions=w.sessions.filter(x=>x.id!==id);w.sessions.push(record);await commit(next,id?'Updated timetable session':'Added timetable session');});
 const form=$('#dialog-form');const check=()=>{const f=new FormData(form),record={id:id||'new',classId:f.get('classId'),subjectId:f.get('subjectId'),teacherId:f.get('teacherId'),roomId:f.get('roomId'),day:+f.get('day'),period:+f.get('period')};const errors=reasons(state,entries(),record);$('#session-check').textContent=errors.length?errors.join(' '):'This assignment passes all required scheduling rules.';};form.elements.classId.onchange=()=>{const c=state.classes.find(x=>x.id===form.elements.classId.value);form.elements.subjectId.innerHTML=c.subjects.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');check();};form.addEventListener('change',check);check();
}
async function runGenerator(){if(!editableWeek())return;const plannedWeek=key;const work=()=>new Promise((resolve,reject)=>{const worker=new Worker('/src/scheduler-worker.js',{type:'module'});const timeout=setTimeout(()=>{worker.terminate();reject(new Error('Planning took too long. Reduce the number of classes or relax restrictions and try again.'));},60000);worker.onmessage=({data})=>{clearTimeout(timeout);worker.terminate();data.error?reject(new Error(data.error)):resolve(data.result);};worker.onerror=()=>{clearTimeout(timeout);worker.terminate();reject(new Error('Could not start the timetable planner.'));};worker.postMessage({state,sessions:entries()});});
 busy=true;render();try{const result=await work();busy=false;if(result.errors.length)throw new Error(result.errors.join(' '));proposal={type:'generate',sessions:result.sessions};modal('Your timetable is ready to review',`<div class="proposal-stats"><strong>${result.sessions.length}<small>scheduled periods</small></strong><strong>${result.missing.reduce((n,x)=>n+x.remaining,0)}<small>unfilled periods</small></strong><strong>${result.sessions.filter(x=>x.locked).length}<small>locks preserved</small></strong></div><p>Applying replaces this draft’s unlocked sessions. Other weeks stay unchanged.</p>${result.notes.length?`<div class="proposal-notes">${result.notes.map(x=>`<p class="issue">${esc(x)}</p>`).join('')}</div>`:'<div class="note">All weekly subject requirements are filled. No hard-rule conflicts were found.</div>'}<p class="muted">The planner searches several greedy arrangements. An unfilled period does not prove that no possible timetable exists.</p><div class="dialog-actions">${btn('Discard','close','','type="button"')}<button class="btn primary" type="submit">Apply timetable</button></div>`,async()=>{if(!editableWeek())return;const next=clone(state);if(key!==plannedWeek)throw new Error('Return to week '+plannedWeek+' before applying this proposal.');ensureWeek(next).sessions=proposal.sessions;await commit(next,'Generated full weekly timetable');proposal=null;},true);}catch(e){toast(e.message,true);}finally{busy=false;render();}}
function planAbsence(teacherId,day){if(!editableWeek())return;const plannedWeek=key;const next=clone(state),t=next.teachers.find(x=>x.id===teacherId);if(!t)return;const sessions=ensureWeek(next).sessions,changes=[],unresolved=[];
 for(const e of sessions.filter(x=>x.teacherId===teacherId&&x.day===day)){if(e.locked){unresolved.push({...e,reason:'Locked session. Unlock it before replacing the teacher.'});continue;}const list=replacements(next,sessions,e).sort((a,b)=>sessions.filter(x=>x.teacherId===a.id).length-sessions.filter(x=>x.teacherId===b.id).length);if(list.length){changes.push({id:e.id,from:t.name,to:list[0].name,subject:subject(next,e)?.name,period:e.period});e.teacherId=list[0].id;}else unresolved.push({...e,reason:'No qualified and available replacement meets all rules.'});}
 modal('Replacement proposal',`<p>${esc(t.name)} · ${esc(state.rules.days[day])} · week of ${key}</p>${changes.length?`<div class="proposal-notes">${changes.map(x=>`<p><strong>${slotTime(state.rules,x.period)} · ${esc(x.subject)}</strong><br>${esc(x.from)} → ${esc(x.to)}</p>`).join('')}</div>`:empty('No replacements found','There may be no sessions on this day or no eligible substitutes.')} ${unresolved.map(x=>`<p class="issue">${slotTime(state.rules,x.period)} · ${esc(subject(state,x)?.name)}: ${esc(x.reason)}</p>`).join('')}<p class="muted">This replaces teachers for this week only. It does not change recurring availability.</p><div class="dialog-actions">${btn('Discard','close','','type="button"')}<button class="btn primary" type="submit" ${!changes.length?'disabled':''}>Apply ${changes.length} replacement(s)</button></div>`,async()=>{if(!editableWeek())return;if(key!==plannedWeek)throw new Error('Return to week '+plannedWeek+' before applying.');await commit(next,'Applied teacher absence replacements');},true);
}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download(`training-studio-${key}.json`,JSON.stringify(state,null,2));}
function filePicker(accept,onFile){const el=document.createElement('input');el.type='file';el.accept=accept;el.onchange=async()=>{if(!el.files[0])return;try{if(el.files[0].size>4_000_000)throw new Error('Choose a file smaller than 4 MB.');await onFile(el.files[0]);}catch(e){toast(e.message,true);}};el.click();}
function restore(){if(!editable())return;filePicker('.json',async file=>{const next=JSON.parse(await file.text()),errors=validateState(next);if(errors.length)throw new Error(errors.slice(0,5).join(' '));confirmAction('Restore this backup?',`Replace the current workspace with <strong>${esc(next.school)}</strong>: ${next.classes.length} classes, ${next.teachers.length} teachers, ${Object.keys(next.weeks).length} saved weeks. Download your current backup first if needed.`,()=>commit(next,'Restored workspace backup'));});}
const cellValue=v=>{if(v===null||v===undefined)return '';if(typeof v==='object')return v.text??(v.richText?v.richText.map(x=>x.text).join(''):v.result??'');return v;};
async function workbook(){if(!globalThis.ExcelJS)throw new Error('Spreadsheet support is still loading. Try again shortly.');return new ExcelJS.Workbook();}
async function exportExcel(template=false){const state=scheduleState();const wb=await workbook();wb.creator='Training Studio';
 const sheet=(name,columns,rows)=>{const ws=wb.addWorksheet(name);ws.columns=columns.map(x=>({header:x,key:x,width:24}));for(const row of rows)ws.addRow(row);ws.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};ws.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF3559EF'}};ws.views=[{state:'frozen',ySplit:1}];};
 if(template){sheet('Teachers',['name','subjects','maxWeekly','maxDaily'],[{name:'Example teacher',subjects:'JavaScript|React',maxWeekly:25,maxDaily:5}]);sheet('Classes',['name','branch','term','size'],[{name:'Example class',branch:'CS',term:1,size:25}]);sheet('Subjects',['className','name','weekly','total','completed','roomType','double','early'],[{className:'Example class',name:'JavaScript',weekly:4,total:60,completed:0,roomType:'Any',double:false,early:true}]);sheet('Rooms',['name','capacity','type'],[{name:'Example room',capacity:30,type:'Classroom'}]);}
 else{sheet('Timetable',['week','day','start','class','subject','teacher','room','locked'],entries().map(e=>({week:key,day:state.rules.days[e.day],start:slotTime(state.rules,e.period),class:state.classes.find(x=>x.id===e.classId)?.name,subject:subject(state,e)?.name,teacher:state.teachers.find(x=>x.id===e.teacherId)?.name,room:state.rooms.find(x=>x.id===e.roomId)?.name,locked:e.locked})));sheet('Unfilled',['class','subject','periods'],canEdit()?missing(state,entries()).map(x=>({class:x.className,subject:x.subjectName,periods:x.remaining})):[]);}
 download(template?'training-studio-import-template.xlsx':`timetable-${key}.xlsx`,await wb.xlsx.writeBuffer(),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
function parseCSV(text){const rows=[];let row=[],field='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quote)throw new Error('CSV contains an unclosed quote.');row.push(field);if(row.some(Boolean))rows.push(row);return rows;}
function importSpreadsheet(){if(!editable())return;modal('Import academy records',`<p>Imports add records. Duplicate class, teacher and room names are rejected so existing records are never silently overwritten. Subjects reference an existing or imported class name.</p>${select('For CSV files, choose the record type','kind',['Teachers','Classes','Subjects','Rooms'].map(x=>[x,x]))}<label>Excel (.xlsx) or CSV file<input type="file" name="file" accept=".xlsx,.csv" required></label><div class="dialog-actions"><button class="btn primary" type="submit">Preview import</button></div>`,async f=>{const file=f.get('file');if(file.size>4_000_000)throw new Error('Choose a file smaller than 4 MB.');const tables={};const records=rows=>{const header=rows.shift().map(x=>String(cellValue(x)).trim());return rows.filter(r=>r.some(v=>cellValue(v)!=='')).map(r=>Object.fromEntries(header.map((k,i)=>[k,cellValue(r[i])])));};if(file.name.toLowerCase().endsWith('.csv'))tables[f.get('kind')]=records(parseCSV(await file.text()));else{const wb=await workbook();await wb.xlsx.load(await file.arrayBuffer());for(const name of ['Teachers','Classes','Subjects','Rooms']){const ws=wb.getWorksheet(name);if(ws){const rows=[];ws.eachRow(r=>rows.push(r.values.slice(1)));if(rows.length)tables[name]=records(rows);}}}
 const next=clone(state),counts=[];for(const [name,list]of Object.entries(tables)){if(list.length>500)throw new Error('Limit each sheet to 500 rows.');counts.push(`${list.length} ${name.toLowerCase()}`);}
 const add=(collection,record)=>{if(next[collection].some(x=>x.name.toLowerCase()===record.name.toLowerCase()))throw new Error(`Duplicate ${collection} name: ${record.name}`);next[collection].push(record);};
 for(const r of tables.Teachers||[])add('teachers',{id:uid(),name:String(r.name||'').trim(),subjects:String(r.subjects||'').split('|').map(x=>x.trim()).filter(Boolean),maxWeekly:Number(r.maxWeekly),maxDaily:Number(r.maxDaily),unavailable:[]});
 for(const r of tables.Classes||[])add('classes',{id:uid(),name:String(r.name||'').trim(),branch:String(r.branch||'').trim(),term:Number(r.term),size:Number(r.size),subjects:[]});
 for(const r of tables.Rooms||[])add('rooms',{id:uid(),name:String(r.name||'').trim(),type:String(r.type||'').trim(),capacity:Number(r.capacity)});
 for(const r of tables.Subjects||[]){const c=next.classes.find(x=>x.name.toLowerCase()===String(r.className).toLowerCase());if(!c)throw new Error(`Class not found: ${r.className}`);if(c.subjects.some(x=>x.name.toLowerCase()===String(r.name).toLowerCase()))throw new Error(`Duplicate subject ${r.name} in ${c.name}`);c.subjects.push({id:uid(),name:String(r.name||'').trim(),weekly:Number(r.weekly),total:Number(r.total),completed:Number(r.completed||0),roomType:String(r.roomType||'Any'),double:String(r.double).toLowerCase()==='true',early:String(r.early).toLowerCase()==='true'});}
 const errors=validateState(next);if(errors.length)throw new Error(errors.slice(0,5).join(' '));if(!counts.length)throw new Error('No recognized sheets. Use the downloadable template.');confirmAction('Import these records?',esc(counts.join(' · ')),()=>commit(next,'Imported spreadsheet records'));});}
async function legacyImport(data){if(!editable())return;const next=clone(state);const source=data.data||data;const teachers=source.instructors||[],classes=source.classes||source.newClassData||data.classes||[];if(!Array.isArray(teachers)||!Array.isArray(classes))throw new Error('Unsupported original backup format.');let addedT=0,addedC=0,emptyClasses=0;for(const t of teachers){if(next.teachers.some(x=>x.name===t.name))continue;next.teachers.push({id:uid(),name:String(t.name),subjects:Array.isArray(t.subjects)?t.subjects.map(String):[],maxWeekly:Math.min(84,Math.max(1,Number(t.maxLoad)||25)),maxDaily:6,unavailable:[]});addedT++;}
 for(const c of classes){const name=String(c.className||c.name||'');if(next.classes.some(x=>x.name===name))continue;const raw=source.subjects?.[name]?.subjects||data.curriculum?.[c.branch]?.[c.term]?.subjects||[];const subs=raw.map(s=>({id:uid(),name:String(s.name),weekly:Math.min(5,Math.max(1,Math.ceil((Number(s.totalPeriods)||40)/12))),total:Number(s.totalPeriods)||40,completed:Math.max(0,(Number(s.totalPeriods)||40)-(Number(s.remainingPeriods ?? s.totalPeriods ?? 40))),roomType:'Any',double:false,early:false}));if(!subs.length)emptyClasses++;next.classes.push({id:uid(),name,branch:String(c.branch||'Unspecified'),term:Number(c.term)||1,size:30,subjects:subs});addedC++;}
 const errors=validateState(next);if(errors.length)throw new Error(errors.slice(0,5).join(' '));confirmAction('Import original project records?',`${addedT} teachers and ${addedC} classes will be added. ${emptyClasses} classes have no matching curriculum. Student counts default to 30 and weekly targets are estimated over 12 weeks; review them after importing. Old HTML timetables and availability will not be imported.`,()=>commit(next,'Imported original project records'));}
async function loadUsers(){try{const {users}=await api('/users');if(view!=='accounts'||!$('#users-list'))return;window.accountRows=users;$('#users-list').innerHTML=`<div class="table-scroll"><table class="data-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><span class="badge">${esc(u.role)}</span></td><td>${btn('Edit','edit-account','',`data-id="${u.id}"`)} ${u.id!==user.id?btn('Delete','delete-account','danger-ghost',`data-id="${u.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`;}catch(e){toast(e.message,true);}}
function editAccount(id){if(!editable())return;const u=window.accountRows?.find(x=>x.id===id)||{name:'',email:'',role:'teacher',teacherId:''};modal(id?'Edit account':'Add account',`<div class="form-grid">${input('Name','name',u.name,'text','required maxlength="120"')}${input('Email','email',u.email,'email','required maxlength="200"')}${select('Role','role',[['teacher','Teacher · published timetable only'],['admin','Administrator · full access']],u.role)}${select('Linked instructor','teacherId',[['','Choose instructor'],...state.teachers.map(t=>[t.id,t.name])],u.teacherId)}${input(id?'New password (leave blank to keep)':'Password','password','','password',`${id?'':'required'} minlength="12" maxlength="256" autocomplete="new-password"`)}</div><p class="muted">Editing an account signs that user out of all sessions.</p><div class="dialog-actions"><button class="btn primary" type="submit">Save account</button></div>`,async f=>{await api('/users',{method:'POST',body:JSON.stringify({...Object.fromEntries(f),id})});close();if(id===user.id)location.reload();else{toast('Account saved');loadUsers();}});}
function login(){const root=$('#app');root.innerHTML=`<div class="login-page"><section class="login-art"><span class="brand-mark">T</span><h1>A clear plan.<br>A better week.</h1><p>People, spaces and subjects.<br>All in the right place.</p><div class="login-cards"><div class="floating-card">09:00 <strong>React workshop</strong><span>Studio 01 · Class A1</span></div><div class="floating-card second">10:40 <strong>Database lab</strong><span>Lab 02 · Class B2</span></div></div></section><section class="login-form"><span class="eyebrow">WELCOME TO TRAINING STUDIO</span><h2>Open your workspace</h2><p>Sign in with your academy account.</p><form id="login-form">${input('Email','email','','email','required autocomplete="username"')}${input('Password','password','','password','required autocomplete="current-password"')}<button class="btn primary" type="submit">Sign in <span>→</span></button><p id="login-error" class="danger" role="alert"></p></form></section></div>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;b.textContent='Signing in…';try{await api('/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await init();}catch(err){$('#login-error').textContent=err.message;b.disabled=false;b.textContent='Sign in';}};}
async function init(){try{const r=await fetch('/api/info');if(r.ok){const info=await r.json();mode='server';user=info.user;ai=info.ai;if(!user)return login();const data=await api('/state');state=data.state;revision=data.revision;if(user.role==='teacher'){scope='teacher';selected=user.teacherId;key=Object.keys(state.weeks).sort().at(-1)||monday();}}else if(r.status===404){mode='local';const saved=localStorage.getItem('training-studio-v2');state=saved?JSON.parse(saved):seed();const errors=validateState(state);if(errors.length)throw new Error('The saved local workspace could not be loaded. Export or recover its browser data before clearing it.');}else throw new Error('The workspace server is unavailable. Please reload shortly.');render();}catch(e){$('#app').innerHTML=`<div class="boot"><h1>Workspace could not open</h1><p>${esc(e.message)}</p><button class="btn primary" data-action="reload">Try again</button></div>`;}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.view){view=b.dataset.view;query='';render();return;}if(b.dataset.scope){scope=b.dataset.scope;selected='';render();return;}if(b.dataset.session)return sessionDialog(b.dataset.session);if(b.dataset.addDay!==undefined)return sessionDialog(null,+b.dataset.addDay,+b.dataset.addPeriod);const id=b.dataset.id;switch(b.dataset.action){case 'close':close();break;case 'reload':location.reload();break;case 'retry':await persist(lastAction);break;case 'logout':await api('/logout',{method:'POST',body:'{}'});location.reload();break;case 'undo':if(editable()&&past.length){const previous=past.pop();future.push(clone(state));await commit(previous,'Undid last change',false);}break;case 'redo':if(editable()&&future.length){const next=future.pop();past.push(clone(state));await commit(next,'Redid change',false);}break;case 'prev-week':case 'next-week':{const d=new Date(key+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+(b.dataset.action==='prev-week'?-7:7));key=d.toISOString().slice(0,10);render();break;}case 'add-teacher':case 'edit-teacher':editTeacher(id);break;case 'availability':availability(id);break;case 'add-class':case 'edit-class':editClass(id);break;case 'subjects':editSubjects(id);break;case 'add-room':case 'edit-room':editRoom(id);break;case 'delete-teacher':deleteEntity('teacher',id);break;case 'delete-class':deleteEntity('class',id);break;case 'delete-room':deleteEntity('room',id);break;case 'add-subject':$('#subject-editors').insertAdjacentHTML('beforeend',subjectRow());break;case 'remove-subject':b.closest('.subject-editor').remove();break;case 'add-session':sessionDialog();break;case 'delete-session':{if(!editableWeek())break;const entry=entries().find(x=>x.id===id);if(entry.locked)throw new Error('Unlock and save this session before deleting it.');confirmAction('Delete session?','Remove this session from the draft timetable?',async()=>{const next=clone(state);ensureWeek(next).sessions=entries().filter(x=>x.id!==id);await commit(next,'Deleted timetable session');});break;}case 'generate':await runGenerator();break;case 'publish':{if(!editable())break;const next=clone(state),w=ensureWeek(next);if(!w.published&&conflicts(w.snapshot||next,w.sessions).length)throw new Error('Resolve all conflicts before publishing.');if(!w.published&&!w.sessions.length)throw new Error('Add timetable sessions before publishing.');const n=missing(next,w.sessions).reduce((n,x)=>n+x.remaining,0);confirmAction(w.published?'Unpublish week?':'Publish this week?',w.published?'Teachers will no longer see this week until it is published again.':`${n?`${n} required periods are still unfilled. `:''}Teachers will be able to see their assigned sessions.`,async()=>{w.published=!w.published;if(w.published){w.snapshot={school:next.school,rules:clone(next.rules),teachers:clone(next.teachers),classes:clone(next.classes),rooms:clone(next.rooms)};}else delete w.snapshot;await commit(next,w.published?'Published weekly timetable':'Unpublished weekly timetable');});break;}case 'open-week':key=id;view='calendar';render();break;case 'copy-week':{if(!editable())break;modal('Copy saved week',input('Destination week','date','','date','required')+'<div class="dialog-actions"><button type="submit" class="btn primary">Copy as draft</button></div>',async f=>{const dest=monday(new Date(f.get('date')+'T00:00:00Z'));if(state.weeks[dest]?.sessions.length||state.weeks[dest]?.published)throw new Error('The destination already has a timetable. Choose an empty week.');const next=clone(state);next.weeks[dest]={sessions:next.weeks[id].sessions.map(x=>({...x,id:uid(),locked:false})),published:false};await commit(next,'Copied weekly timetable');key=dest;view='calendar';render();});break;}case 'delete-week':if(editable())confirmAction('Delete saved week?',`Delete all sessions saved for ${id}?`,async()=>{const next=clone(state);delete next.weeks[id];await commit(next,'Deleted saved week');});break;case 'promote':{if(!editable())break;const c=state.classes.find(x=>x.id===id);confirmAction('Promote '+esc(c.name)+'?',`Move from term ${c.term} to ${c.term+1}. The curriculum and progress will be preserved. Edit subjects separately when the next term curriculum is ready.`,async()=>{const next=clone(state);next.classes.find(x=>x.id===id).term++;await commit(next,'Promoted class '+c.name);});break;}case 'print':window.print();break;case 'backup':backup();break;case 'restore':restore();break;case 'export-excel':await exportExcel();break;case 'template':await exportExcel(true);break;case 'import-sheet':importSpreadsheet();break;case 'legacy':await legacyImport(await (await fetch('/legacy-data.json')).json());break;case 'legacy-backup':filePicker('.json',async f=>legacyImport(JSON.parse(await f.text())));break;case 'add-account':case 'edit-account':editAccount(id);break;case 'delete-account':if(editable())confirmAction('Delete account?','This revokes access and all active sessions for this account.',async()=>{await api('/users/'+id,{method:'DELETE',body:'{}'});close();loadUsers();});break;}}catch(err){toast(err.message,true);}});
document.addEventListener('change',e=>{if(e.target.id==='week-input'&&e.target.value){key=monday(new Date(e.target.value+'T00:00:00Z'));render();}if(e.target.id==='entity-select'){selected=e.target.value;render();}if(e.target.id==='search'){query=e.target.value;render();}});
document.addEventListener('submit',async e=>{const id=e.target.id;if(!['rules-form','absence-form','ai-form'].includes(id))return;e.preventDefault();if(!editable())return;try{const f=new FormData(e.target);if(id==='rules-form'){const next=clone(state),days=f.getAll('days');if(JSON.stringify(days)!==JSON.stringify(state.rules.days)&&Object.values(state.weeks).some(w=>w.sessions.length))throw new Error('Working days can only change when all saved timetables are empty. Back up your history first.');next.school=f.get('school').trim();next.rules={days,start:f.get('start'),periods:+f.get('periods'),duration:+f.get('duration'),breaks:f.get('breaks').trim()?f.get('breaks').split(',').map(x=>Number(x.trim())-1):[]};await commit(next,'Updated scheduling rules');}else if(id==='absence-form')planAbsence(f.get('teacherId'),+f.get('day'));else{const button=e.target.querySelector('button');button.disabled=true;button.textContent='Thinking…';try{const r=await api('/assistant',{method:'POST',body:JSON.stringify({prompt:f.get('prompt')})});if(r.error)throw new Error(r.error);planAbsence(r.teacherId,r.day);}finally{button.disabled=false;button.textContent='Preview suggestion';}}}catch(err){toast(err.message,true);}});
let dragged=null;document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-session]');if(!card||card.draggable!==true)return;dragged=card.dataset.session;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',e=>{if(dragged&&e.target.closest('[data-drop-day]')){e.preventDefault();e.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',async e=>{const cell=e.target.closest('[data-drop-day]');if(!cell||!dragged)return;e.preventDefault();const id=dragged;dragged=null;if(!editableWeek())return;try{const session=entries().find(x=>x.id===id);if(!session||session.locked)return;const record={...session,day:+cell.dataset.dropDay,period:+cell.dataset.dropPeriod};const errors=reasons(state,entries(),record);if(errors.length)throw new Error(errors.join(' '));const next=clone(state);ensureWeek(next).sessions=entries().map(x=>x.id===id?record:x);await commit(next,'Moved timetable session');}catch(err){toast(err.message,true);}});
document.addEventListener('dragend',()=>dragged=null);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal').open)close();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('input,textarea,select')&&!$('#modal').open){e.preventDefault();document.querySelector(`[data-action="${e.shiftKey?'redo':'undo'}"]`)?.click();}});
window.addEventListener('beforeunload',e=>{if(saving||blocked){e.preventDefault();e.returnValue='';}});
init();

window.addEventListener('storage',e=>{if(mode==='local'&&e.key==='training-studio-v2'){blocked=true;render();toast('This workspace changed in another tab. Reload the saved version before editing.',true);}});
